    payload.forEach((x) => {
      if (x.pos === 0) maj.push(x.type);
      if (x.pos === 3) min.push(x.type);
    });

    const count = (arr, ch) => arr.reduce((a, v) => a + (v === ch ? 1 : 0), 0);

    return {
      d: count(maj, "d") - count(min, "d"),
      i: count(maj, "i") - count(min, "i"),
      s: count(maj, "s") - count(min, "s"),
