Now the token generation. Let me include it as a faithful client-side mechanism, guarded in try/catch. It uses WebCrypto AES-GCM.

```js
  function strToBytes(s) {
    return new TextEncoder().encode(s);
  }

  async function generateToken(res) {
    const SECRET = "disc@v1::client-only";
    const hash = await crypto.subtle.digest("SHA-256", strToBytes(SECRET));
    const key = await crypto.subtle.importKey("raw", hash, { name: "AES-GCM" }, false, ["encrypt", "decrypt"]);
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const plain = strToBytes(JSON.stringify(res));
    const ct = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, plain);
    const token = b64url(iv.concat(new Uint8Array(ct)));
    // store in sessionStorage (faithful to mechanism, client-only)
    try { sessionStorage.setItem("disc.token", token); } catch (e) {}
    return token;
  }

  function b64url(buf) {
    let b = "";
    for (let i = 0; i < buf.length; i += 3) {
      const a = buf[i], x = (buf[i+1] || 0) & 255, y = buf[i+2] || 0;
      let c = a >> 2;
      let d = ((a & 3) << 4) | ((x >> 4) & 15);
      let e = ((x & 15) << 2) | (y >> 6);
      let f = y & 63;
      const p = b64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+-";
      b += p[c] + p[d] + p[e] + p[f];
    }
    return b.replace(/={1,2}$/g, "");
  }
