  const scoreSpan=$("#scoreSpan");
  const scoreChips=$("#scoreChips");
  const discShare=$("#discShare");
  const copyBtn=$("#copyBtn");
  const restartBtn=$("#restartBtn");

  let current=0, finished=false, pointerId=0;

  /* ===== Группировка по шагам ===== */
  const stepGroups=Array.from({length:STEPS},()=>[]);
  QUESTIONS.forEach(q=>{ stepGroups[Math.floor((q.id-1)/3)].push(q); });

  /* ===== Построение DOM ===== */
  function buildTabs(){
    TAB_NAMES.forEach((name,s)=>{
      const b=document.createElement("button");
      b.type="button"; b.className="tab"; b.setAttribute("role","tab");
      b.setAttribute("aria-selected", s===0?"true":"false");
      b.setAttribute("data-step",s);
      b.textContent=name;
      b.addEventListener("click", ()=>{ if(!finished) render(s); });
      tabsEl.appendChild(b);
    });
  }
  function buildPanes(){
    for(let s=0;s<STEPS;s++){
      const pane=document.createElement("section");
      pane.className="pane"; pane.id="step-"+s; pane.dataset.step=s; pane.hidden=true;
      stepGroups[s].forEach((q,n)=> pane.appendChild(makeCard(q,n+1)));
      grid.appendChild(pane);
    }
    $$(".list").forEach(attachDrag);
  }
  function makeCard(q,n){
    const card=document.createElement("div"); card.className="qcard";
    const num=document.createElement("div"); num.className="num"; num.textContent="Вопрос "+n;
    const top=document.createElement("div"); top.className="lbl top"; top.textContent="Я наиболее";
    const list=makeList(q);
    const bot=document.createElement("div"); bot.className="lbl bot"; bot.textContent="Я наименее";
    card.append(num,top,list,bot);
    return card;
  }
  function makeList(q){
    const ul=document.createElement("ul"); ul.className="disc-list"; ul.id="draggable-list"+q.id;
    q.items.forEach(it=>{
      const li=document.createElement("li"); li.className="item"; li.setAttribute("data-type",it.t);
      const h=document.createElement("span"); h.className="handle"; h.setAttribute("aria-hidden","true");
      h.innerHTML=HANDLE_SVG;
      const txt=document.createElement("span"); txt.className="txt"; txt.textContent=it.x;
      li.append(h,txt); ul.appendChild(li);
    });
    return ul;
  }

  /* ===== Перетаскивание (Pointer Events: мышь + тач; на тач — за "точечки") ===== */
  function attachDrag(list){
    let dragging=null, captured=false;
    function onDown(e){
      const item=e.target.closest("li.item");
      if(!item || !list.contains(item)) return;
      const isTouch=e.pointerType==="touch";
      if(isTouch && !e.target.closest(".handle")) return;   /* тач — только за handle */
      e.preventDefault();
      dragging=item; pointerId=e.pointerId;
      item.classList.add("is-drag"); list.classList.add("is-reordering");
      try{ list.setPointerCapture(pointerId); captured=true; }catch(_x){}
      onMove(e);
    }
    function onMove(e){
      if(!dragging) return;
      e.preventDefault();
      const lis=Array.prototype.slice.call(list.children);
      const others=lis.filter(li=>li!==dragging);
      if(others.length===0) return;
      const y=e.clientY;
      let anchor=null;
      for(const li of others){
        const r=li.getBoundingClientRect();
        const mid=r.top+r.height/2;
        if(y>=mid) anchor=li; else break;
      }
      if(anchor) list.insertBefore(dragging, anchor.nextSibling);
      else list.insertBefore(dragging, others[0]);
    }
    function onUp(){
      if(dragging){ dragging.classList.remove("is-drag"); list.classList.remove("is-reordering"); dragging=null; }
      if(captured){ try{ list.releasePointerCapture(pointerId); }catch(_x){} captured=false; }
      pointerId=0;
    }
    list.addEventListener("pointerdown",onDown,{passive:false});
    list.addEventListener("pointermove",onMove,{passive:false});
    list.addEventListener("pointerup",onUp);
    list.addEventListener("pointercancel",onUp);
  }

  /* ===== Навигация ===== */
  function render(s){
    if(finished) return;
    current=s;
    $$(".pane").forEach(p=>{
      const sp=parseInt(p.dataset.step,10);
      p.hidden = sp!==s;
      p.classList.toggle("show", sp===s);
    });
    $$(".tab").forEach(b=>{
      const on=parseInt(b.getAttribute("data-step"),10)===s;
      b.classList.toggle("is-active",on);
      b.setAttribute("aria-selected", on?"true":"false");
    });
    prevBtn.disabled=(s===0);
    nextBtn.textContent= (s===STEPS-1)?"Завершить тест":"Далее";
    progressFill.style.width=((s+1)/STEPS*100)+"%";
  }
  function openModal(){
    overlay.removeAttribute("hidden"); overlay.classList.add("open");
    document.body.classList.add("no-scroll");
    if(finished){ wizard.hidden=true; resultSection.hidden=false; }
    else{ render(0); const f=$("#discTabs .tab"); if(f) f.focus(); }
  }
  function closeModal(){
    overlay.classList.remove("open"); overlay.setAttribute("hidden","");
    document.body.classList.remove("no-scroll");
  }

  /* ===== Подсчёт (логика как в оригинале: major=позиция 0, minor=позиция 3) ===== */
  function score(){
    const maj=[], min=[];
    const lists=document.querySelectorAll(".disc-list");
    lists.forEach(ul=>{
      const lis=Array.prototype.slice.call(ul.children);
      lis.forEach((li,idx)=>{
        const type=li.getAttribute("data-type");
        if(idx===0) maj.push(type);
        else if(idx===lis.length-1) min.push(type);
      });
    });
    const count=(arr,ch)=>arr.reduce((a,v)=>a+(v===ch?1:0),0);
    return { d:count(maj,"d")-count(min,"d"), i:count(maj,"i")-count(min,"i"),
             s:count(maj,"s")-count(min,"s"), c:count(maj,"c")-count(min,"c") };
  }
  function finish(){
    finished=true;
    const res=score();
    scoreSpan.textContent="D:"+res.d+", I:"+res.i+", S:"+res.s+", C:"+res.c;
    renderResult(res);
    wizard.hidden=true; resultSection.hidden=false;
    discShare.value="Мой DISC-профиль: "+scoreSpan.textContent;
    makeToken(res).catch(()=>{});
  }
  function renderResult(r){
    scoreChips.innerHTML="";
    ["D","I","S","C"].forEach(k=>{
      const v=r[k.toLowerCase()];
      const chip=document.createElement("div"); chip.className="score-chip";
      const letter=document.createElement("div"); letter.className="letter"; letter.textContent=k;
      const val=document.createElement("div"); val.className="val "+(v>0?"pos":v<0?"neg":"zero"); val.textContent=v;
      chip.append(letter,val); scoreChips.appendChild(chip);
    });
  }

  /* ===== "Шифрование" результата в URL-токен (AES-GCM через WebCrypto, client-only) ===== */
  function strToBytes(s){ return new TextEncoder().encode(s); }
  function b64url(buf){
    const b64="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+-";
    let out="";
    for(let i=0;i<buf.length;i+=3){
      const p0=buf[i], p1=i+1<buf.length?buf[i+1]:0, p2=i+2<buf.length?buf[i+2]:0;
      out+=b64[p0>>2]+b64[((p0&3)<<4)|(p1>>4)]+b64[((p1&15)<<2)|(p2>>6)]+b64[p2&63];
    }
    return out.replace(/==?$/,"");
  }
  async function makeToken(res){
    const SECRET="disc@v1::client-only";
    const hash=await crypto.subtle.digest("SHA-256",strToBytes(SECRET));
    const key=await crypto.subtle.importKey("raw",hash,{name:"AES-GCM"},false,["encrypt","decrypt"]);
    const iv=crypto.getRandomValues(new Uint8Array(12));
    const ct=await crypto.subtle.encrypt({name:"AES-GCM",iv},key,strToBytes(JSON.stringify(res)));
    const token=b64url(iv.concat(new Uint8Array(ct)));
    try{ sessionStorage.setItem("disc.token",token); }catch(_x){}
    return token;
  }

  /* ===== Кнопки ===== */
  openBtn.addEventListener("click",openModal);
  closeBtn.addEventListener("click",closeModal);
  nextBtn.addEventListener("click",()=>{
    if(finished) return;
    if(current<STEPS-1) render(current+1); else finish();
  });
  prevBtn.addEventListener("click",()=>{ if(!finished && current>0) render(current-1); });
  restartBtn.addEventListener("click",()=>{
    finished=false; current=0;
    scoreSpan.textContent="D:0, I:0, S:0, C:0"; scoreChips.innerHTML="";
    wizard.hidden=false; resultSection.hidden=true;
    render(0);
  });
  copyBtn.addEventListener("click",()=>{
    const val=discShare.value;
    if(navigator.clipboard&&navigator.clipboard.writeText){
      navigator.clipboard.writeText(val).catch(()=>{}).then(flash);
    }else{
      discShare.select();
      try{document.execCommand("copy");}catch(_x){}
      flash();
    }
  });
  function flash(){
    copyBtn.textContent="Скопировано!";
    copyBtn.classList.add("ok");
    setTimeout(()=>{ copyBtn.textContent="Copy"; copyBtn.classList.remove("ok"); },1400);
  }

  /* ===== Инициализация ===== */
  buildTabs();
  buildPanes();
  render(0);
  overlay.addEventListener("click",e=>{ if(e.target===overlay) closeModal(); });
  document.addEventListener("keydown",e=>{ if(e.key==="Escape"&&overlay.classList.contains("open")) closeModal(); });
})();
"""
)

