.score-chip .val{font-size:28px;font-weight:800;margin-top:2px;display:block}
.score-chip .val.pos{color:var(--top)}
.score-chip .val.neg{color:var(--bottom)}
.score-chip .val.zero{color:var(--muted)}
.result__subtitle{margin:4px 24px 4px;color:var(--ink);font-size:14px}
.result__subtitle a{color:var(--accent);font-weight:600;text-decoration:underline}
.result__disclaimer{margin:2px 24px 18px;color:var(--muted);font-size:13.5px}
.result__disclaimer span{font-weight:800}
.result__link-wrap{margin:0 24px 4px}
.result__link-title{margin:0 0 10px;font-weight:700;font-size:14px}
.copyfield{display:flex;gap:8px;border:1px solid var(--line);border-radius:12px;background:#fff;padding:6px;max-width:420px}
.copyfield__input{flex:1;min-width:0;border:0;padding:10px 12px;font-family:var(--font);font-size:13.5px;color:var(--muted);background:var(--bg);border-radius:8px}
.copyfield__btn{flex:none;border:0;border-radius:8px;background:var(--accent);color:#fff;padding:10px 18px;font-weight:600;cursor:pointer;font-family:var(--font);font-size:14px}
.copyfield__btn:hover{background:var(--accent-d)}
.copyfield__btn.ok{background:#1f7a3f}
@media (max-width:520px){
  .result__title{margin-left:14px;margin-right:14px}
  .result__score,.score-chips,.result__subtitle,.result__disclaimer,.result__link-wrap,.copyfield{margin-left:14px;margin-right:14px}
}
